            Node("high_has_failure", "high has failure", "Exact declaration: theorem high_has_failure {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hminimal : Minimal adjacency selection) (deleted : Vertex) (hhigh : High adjacency selection deleted) : ∃ outside, Failure adjacency selection deleted outside.", DescribeRole.Theorem),
            Node("adjacent_high_survives", "adjacent high survives", "Exact declaration: theorem adjacent_high_survives {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (center deleted outside : Vertex) (hhigh : High adjacency selection center) (hdifferent : center ≠ deleted) (hedge : adjacency outside center) : TwoAt adjacency (fun vertex => selection vertex ∧ vertex ≠ deleted) outside.", DescribeRole.Theorem),
            Node("selected_leaf_has_private_witness", "selected leaf has private witness", "Exact declaration: theorem selected_leaf_has_private_witness {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (hirreflexive : ∀ vertex, ¬ adjacency vertex vertex) (hsymmetric : ∀ first second, adjacency first second → adjacency second first) (hminimal : Minimal adjacency selection) (hnoisolates : ∀ vertex, selection vertex → ∃ neighbor, selection neighbor ∧ adjacency vertex neighbor) (leaf support : Vertex) (hleaf : selection leaf) (hhigh : High adjacency selection support) (hsupport : adjacency leaf support) (hunique : ∀ neighbor, selection neighbor → adjacency leaf neighbor → neighbor = support) : ∃ outside, Failure adjacency selection leaf outside ∧ adjacency outside leaf ∧ ∀ neighbor, selection neighbor → adjacency outside neighbor → neighbor = leaf.", DescribeRole.Theorem),
            Node("failure_witnesses_disjoint", "failure witnesses disjoint", "Exact declaration: theorem failure_witnesses_disjoint {Vertex : Type} (adjacency : Vertex → Vertex → Prop) (selection : Vertex → Prop) (hforms : Forms adjacency selection) (first second outside : Vertex) (hfirst : High adjacency selection first) (hsecond : High adjacency selection second) (hfailureFirst : Failure adjacency selection first outside) (hfailureSecond : Failure adjacency selection second outside) : first = second.", DescribeRole.Theorem),
