            Node("witness_capacity", "witness capacity", "Exact declaration: theorem witness_capacity (maximum selectedDegree outsideDegree : Nat) (adjacent : Prop) (hselected : selectedDegree ≤ maximum) (houtside : outsideDegree ≤ 2) (hadjacent : adjacent → selectedDegree + 1 ≤ maximum) (hnonadjacent : ¬ adjacent → outsideDegree ≤ 1) : selectedDegree + outsideDegree ≤ maximum + 1.", DescribeRole.Theorem)), []));
